verus! {
    /// Given two positive 8-bit integers x and y as inclusive bounds,
    /// return the largest even integer in [x, y], or -1 if x>y or
    /// if there is no even integer in the interval.
    fn choose_num(x: i8, y: i8) -> i8
        requires
            x > 0 && y > 0,
        ensures
            // If the interval is empty, we get -1
            (x > y ==> result == -1)
            &&
            // If x <= y but there is no even in [x,y], we get -1
            (x <= y &&
             (forall|e: i8| x <= e && e <= y && e % 2 == 0 ==> false)
             ==> result == -1)
            &&
            // Otherwise, we return an even in [x,y] that is >= every other even in [x,y]
            (x <= y &&
             (exists|e: i8| x <= e && e <= y && e % 2 == 0)
             ==>
             x <= result && result <= y && result % 2 == 0
             && forall|e: i8| x <= e && e <= y && e % 2 == 0 ==> e <= result)
    {
        // Case 1: empty interval
        if x > y {
            return -1;
        }

        // Compute the greatest even ≤ y
        let c: i8 = if y % 2 == 0 {
            y
        } else {
            y - 1
        };

        // If that candidate still lies below x, there is no even in [x,y]
        if c < x {
            return -1;
        }

        // Otherwise c is even, in [x,y], and is the largest even in the interval
        c
    }
}

